const review = get(
	ctx.subject.employment.employee_extension_data,
	'term_facts.comprehensive_overtime_review',
	null
);
const from = ctx.run.salary_coverage.from;
const to = ctx.run.salary_coverage.to;
const terms = ctx.subject.employment.terms;
if (get(terms, 'statutory_work_category', '') !== 'COMPREHENSIVE') return false;
if (get(terms.rate, 'unit', 'MONTHLY') !== 'MONTHLY') return false;
if (review == null) return false;
if (review.month !== from.slice(0, 7)) return false;
if (review.reference === '') return false;
if (!(review.settlement_on >= from)) return false;
if (!(review.settlement_on <= to)) return false;
return Number(review.excess_nonholiday_hours) > 0;

